import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import { Row, Col, Form, Button, notification } from 'antd'
import _ from 'lodash/object'
import IntlMessages from '../../../../../components/utility/intlMessages'
import policyAction from '../../../../../redux/policy/actions'
import CircularLoader from '../../../../../components/CircularLoader'
import endorseActions from '../../../../../redux/Endorsement/actions'
import { SendoContainerStyle, SendoFormContainer, PolicyInsuredStyle } from './index.style'
import { showErrorMessage } from '../../../../../helpers/errorUtils'
import { LANG_STRINGS } from '../../../../../constants/lang'
import { getFormItems } from '../../../../../components/utility/formItems'
import validator from '../../../../../helpers/validator'
import { ENDORSE_LANG } from '../../../constants'
import SendoThankYou from '../../../SendoPersonalAccidentProtectionPro/components/SendoPersonalAccidentThankYou'

const { getPolicyDetails } = policyAction
const {
  submitGosureEndorseForm,
  resetGosureEndorseRedux,
  getCityData,
  getDistrictData,
  getTownData
} = endorseActions

class SendoPersonalAccidentContainer extends Component {
  constructor (props) {
    super(props)
    this.state = {
      filledData: {}
    }
  }
  static propTypes = {
    id: PropTypes.string
  }

  async componentDidMount () {
    const { id } = this.props
    await this.props.getPolicyDetails(id)
    await this.props.getCityData()
  }

  componentWillReceiveProps=(nextProps) => {
    const { submitSendoError, gosureDetailsMessage } = nextProps
    const { filledData } = this.state
    const formData = nextProps.form.getFieldsValue()
    const { city, district, town } = formData
    if (submitSendoError && gosureDetailsMessage && (gosureDetailsMessage !== 'success')) {
      notification['error']({
        message: this.intlText({ id: 'Error' }),
        description: this.intlText({ id: _.get(gosureDetailsMessage[0], 'err', '') })
      })
      //   // this is clear the error messsage if any left after popup show
      this.props.resetGosureEndorseRedux(['gosureDetailsMessage'])
    }
    if (gosureDetailsMessage !== 'success') {
      if (city !== '' && !!city) {
        if (!filledData.hasOwnProperty('city') || (filledData.city !== city)) {
          let data = {
            'city': city
          }
          this.setState({
            filledData: data
          }, () => {
            this.props.getDistrictData({ filter: city })
          })
          nextProps.form.setFieldsValue({
            district: '',
            town: ''
          })
        }
      }
      if (district !== '' && !!district) {
        if (!filledData.hasOwnProperty('district') || (filledData.district !== district)) {
          let data = {
            'city': city,
            'district': district
          }
          this.setState({
            filledData: data
          }, () => {
            this.props.getTownData({ filter: district })
          })
          nextProps.form.setFieldsValue({
            town: ''
          })
        }
      }
      if (town !== '' && !!town) {
        if (!filledData.hasOwnProperty('town') || (filledData.town !== town)) {
          let data = {
            'city': city,
            'district': district,
            'town': town
          }
          this.setState({
            filledData: data
          })
        }
      }
    }
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  handleFormSubmit = async (e) => {
    e.preventDefault()
    const { form } = this.props
    const formBody = form.getFieldsValue()
    const { policyHolderName, policyHolderAddress, policyHolderEmail, vehicle_plate, city, district, town, aggrement } = formBody
    if (!aggrement) {
      form.setFieldsValue({
        aggrement: undefined
      })
    }
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const body = {
      'name': policyHolderName,
      'email': policyHolderEmail,
      'address': policyHolderAddress.concat(`, ${town}`, `, ${district}`, `, ${city}`),
      'vehicle_plate': vehicle_plate
    }
    this.props.submitGosureEndorseForm({
      body,
      id: this.props.id
    })
  }

  getTopSection = (detailsData) => {
    return (
      <React.Fragment>
        {
          this.getPolicyHolderName()
        }
      </React.Fragment>
    )
  }
  getBottomSection = (detailsData) => {
    return (
      <React.Fragment>
        {
          this.getInsuredInfo()
        }
      </React.Fragment>
    )
  }

  getPolicyHolderName = () => {
    return (
      <PolicyInsuredStyle>
        {
          getFormItems.call(this, {
            formName: 'policyHolderName',
            type: 'alphanumeric',
            label: LANG_STRINGS.name,
            placeHolder: ENDORSE_LANG.sendoBikeNamePlaceholder,
            required: true,
            validator: validator.checkValidator
          })
        }
        {
          getFormItems.call(this, {
            formName: 'policyHolderEmail',
            type: 'email',
            label: LANG_STRINGS.email,
            placeHolder: ENDORSE_LANG.sendoBikeEmailPlaceholder,
            required: true,
            validator: validator.checkValidator
          })
        }
        {
          getFormItems.call(this, {
            formName: 'policyHolderAddress',
            type: 'textarea',
            row: 1,
            label: LANG_STRINGS.address,
            placeHolder: ENDORSE_LANG.sendoBikeAddressPlaceholder,
            required: true,
            validator: validator.checkValidAddress
          })
        }
        {
          getFormItems.call(this, {
            formName: 'city',
            type: 'choices',
            label: LANG_STRINGS.cityProvince,
            placeHolder: LANG_STRINGS.cityProvince,
            required: true,
            options: this.props.cityData || [],
            optionKey: 'display_name',
            validator: validator.checkValidator
          })
        }
        {
          getFormItems.call(this, {
            formName: 'district',
            type: 'choices',
            label: LANG_STRINGS.district,
            placeHolder: LANG_STRINGS.district,
            required: true,
            options: this.props.districtData || [],
            optionKey: 'display_name',
            validator: validator.checkValidator
          })
        }
        {
          getFormItems.call(this, {
            formName: 'town',
            type: 'choices',
            label: LANG_STRINGS.townWardVillage,
            placeHolder: LANG_STRINGS.townWardVillage,
            required: true,
            options: this.props.townData || [],
            optionKey: 'display_name',
            validator: validator.checkValidator
          })
        }
      </PolicyInsuredStyle>
    )
  }

  getInsuredInfo = () => {
    return (
      <PolicyInsuredStyle>
        {
          getFormItems.call(this, {
            formName: 'vehicle_plate',
            type: 'alphanumeric',
            label: ENDORSE_LANG.vechilePlate,
            placeHolder: ENDORSE_LANG.vechilePlate,
            required: true,
            validator: validator.checkValidator
          })
        }
      </PolicyInsuredStyle>
    )
  }

  render () {
    const {
      policyDetailLoading, detailsData, submitSendoLoading,
      policyDetailError, gosureDetailsMessage
    } = this.props
    const isSuccessFulEndorse = gosureDetailsMessage === 'success' || (_.get(detailsData, 'EndorsementStatus', '') === 'SUCCESS')
    const formItemLayout = {
      labelCol: {
        xs: { span: 24 },
        sm: { span: 11 }
      },
      wrapperCol: {
        xs: { span: 24 },
        sm: { span: 11 }
      }
    }
    return (
      <SendoContainerStyle>
        {
          isSuccessFulEndorse ? <SendoThankYou thankYouMessage={ENDORSE_LANG.sendoBikeThankYouMessage} /> : policyDetailError ? showErrorMessage()
            : <CircularLoader isSpining={policyDetailLoading || submitSendoLoading}>
              <h1 className='order-heading'><IntlMessages id={LANG_STRINGS.orderNumber} /> : {_.get(detailsData, 'Request.order_number', '')}</h1>
              <Form
                onSubmit={this.handleFormSubmit}
                id='myForm'
                {...formItemLayout}
              >
                <SendoFormContainer>
                  <div className='name-section'>
                    <IntlMessages id={ENDORSE_LANG.motorBikeOwnerData} />
                  </div>
                  <Row type='flex' justify='center'>
                    <Col xs={24} sm={23} xl={15} md={15}>
                      {this.getTopSection(detailsData)}
                    </Col>
                  </Row>
                </SendoFormContainer>
                <SendoFormContainer>
                  <div className='name-section'>
                    <IntlMessages id={ENDORSE_LANG.motorBikeData} />
                  </div>
                  <Row type='flex' justify='center'>
                    <Col xs={24} sm={23} xl={15} md={15}>
                      {this.getBottomSection(detailsData)}
                    </Col>
                  </Row>
                </SendoFormContainer>
                <Row type='flex' justify='center'>
                  <Col span={24}>

                    {
                      getFormItems.call(this, {
                        formName: 'aggrement',
                        type: 'checkbox',
                        className: 'checkbox',
                        label: ENDORSE_LANG.acceptMotorBikeAggrement,
                        // placeHolder: ENDORSE_LANG.vechilePlate,
                        required: true,
                        validator: validator.checkValidator
                      })
                    }

                  </Col>
                </Row>
                <Row type='flex' justify='center'>
                  <Col xs={24} sm={23} xl={5} md={5}>
                    <Button
                      type='primary'
                      className='form-btn'
                      htmlType='submit'
                      key='submit'
                    >
                      <IntlMessages id={LANG_STRINGS.submit} />
                    </Button>
                  </Col>
                </Row>
              </Form>
            </CircularLoader>
        }
      </SendoContainerStyle>
    )
  }
}

const SendoPersonalAccidentContainerWrapped = Form.create()(SendoPersonalAccidentContainer)
export default connect(
  state => ({
    getPolicyDetailResult: state.Policy.getPolicyDetailResult,
    policyDetailLoading: state.Loading.POLICY_DETAILS,
    policyDetailError: state.Error.POLICY_DETAILS,
    gosureDetailsMessage: state.Endorsement.gosureDetailsMessage,
    submitSendoLoading: state.Loading.SUBMIT_GOSURE_ENDORSE,
    submitSendoError: state.Error.SUBMIT_GOSURE_ENDORSE,
    detailsData: state.Policy.detailsData,
    cityData: state.Endorsement.cityData,
    districtData: state.Endorsement.districtData,
    townData: state.Endorsement.townData
  }),
  {
    getPolicyDetails,
    getCityData,
    getDistrictData,
    getTownData,
    resetGosureEndorseRedux,
    submitGosureEndorseForm
  }
)(injectIntl(SendoPersonalAccidentContainerWrapped))
