import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import { get } from 'lodash/object'
import { Form, Button, notification, Tooltip } from 'antd'
import IntlMessages from '../../../../../components/utility/intlMessages'
import policyAction from '../../../../../redux/policy/actions'
import CircularLoader from '../../../../../components/CircularLoader'
import endorseActions from '../../../../../redux/Endorsement/actions'
import { showErrorMessage } from '../../../../../helpers/errorUtils'
import { EndorseContainerStyle, DataFormStyle, CircleTextStyle, DisplayInlineFCC } from './index.style'
import { getFormItems } from '../../../../../components/utility/formItems'
import validator from '../../../../../helpers/validator'
import { LANG_STRINGS } from '../../../../../constants/lang'
import { ENDORSE_LANG, BUKALAPAK_ENDORSE_FORM, MOTOR_DATA_FORM } from '../../../constants'
import EndorseWelcome from '../../../components/EndorseWelcome'

const { getPolicyDetails } = policyAction
const {
  submitGosureEndorseForm, resetGosureEndorseRedux,
  getBikeBrandList, getBikeModelList
} = endorseActions

class BukalapakContainer extends Component {
  static propTypes = {
    id: PropTypes.string
  }
  componentDidMount () {
    const { id } = this.props
    this.props.getPolicyDetails(id)
    this.props.getBikeBrandList()
    this.props.getBikeModelList()
  }

  componentWillReceiveProps (nextProps) {
    const { submitSendoError, gosureDetailsMessage } = nextProps
    if (submitSendoError && gosureDetailsMessage && (gosureDetailsMessage !== 'success')) {
      notification['error']({
        message: this.intlText({ id: 'Error' }),
        description: this.intlText({ id: gosureDetailsMessage })
      })
      // this is clear the error messsage if any left after popup show
      this.props.resetGosureEndorseRedux(['gosureDetailsMessage'])
    }
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  handleFormSubmit = async (e) => {
    e.preventDefault()
    const { form } = this.props
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const formBody = form.getFieldsValue()
    // the form contains the same field as a name
    // as required in request body
    const body = {
      ...formBody,
      dob: formBody.dob.format('YYYY-MM-DD')
    }
    this.props.submitGosureEndorseForm({
      body,
      id: this.props.id
    })
  }

  getPolicyHolderData = () => {
    return (
      <DataFormStyle>
        {this.getNameTitle(ENDORSE_LANG.policyHolder)}
        {
          BUKALAPAK_ENDORSE_FORM.map(policyHolder => getFormItems.call(this, policyHolder))
        }
      </DataFormStyle>
    )
  }

  getToolTip = () => {
    return (
      <Tooltip
        placement='topLeft'
        title={ENDORSE_LANG.chassisNumerGet}
        arrowPointAtCenter
      >
        <CircleTextStyle>?</CircleTextStyle>
      </Tooltip>
    )
  }

  getMototCycleData = () => {
    return (
      <DataFormStyle>
        {this.getNameTitle(ENDORSE_LANG.motorCycleData)}
        {
          MOTOR_DATA_FORM.map(policyHolder => {
            switch (policyHolder.formName) {
              case 'brand':
                return getFormItems.call(this, {
                  ...policyHolder,
                  options: (this.props.bikeBrandList.length ? this.props.bikeBrandList : []),
                  optionKey: 'display_name'
                })
              case 'model':
                return getFormItems.call(this, {
                  ...policyHolder,
                  options: (this.props.bikeModelList.length ? this.props.bikeModelList : []),
                  optionKey: 'display_name'
                })
              case 'chassis_number':
                return getFormItems.call(this, {
                  ...policyHolder,
                  reactLabel: (
                    <DisplayInlineFCC>
                      {this.intlText({ id: policyHolder.label })}
                      {this.getToolTip()}
                    </DisplayInlineFCC>
                  )
                })
              default:
                return getFormItems.call(this, policyHolder)
            }
          })
        }
      </DataFormStyle>
    )
  }

  getNameTitle = (title) => {
    return (
      <div className='name-section'>
        <IntlMessages id={title} />
      </div>
    )
  }

  render () {
    const {
      policyDetailLoading, detailsData, submitSendoLoading,
      policyDetailError, gosureDetailsMessage, brandLoading, modelLoading
    } = this.props
    const isSuccessFulEndorse = gosureDetailsMessage === 'success' || (get(detailsData, 'EndorsementStatus', '') === 'SUCCESS')
    const formItemLayout = {
      labelCol: {
        xs: { span: 24 },
        sm: { span: 5 }
      },
      wrapperCol: {
        xs: { span: 24 },
        sm: { span: 5 }
      }
    }
    return (
      <EndorseContainerStyle>
        {
          isSuccessFulEndorse ? <EndorseWelcome /> : policyDetailError ? showErrorMessage()
            : <CircularLoader isSpining={policyDetailLoading || submitSendoLoading}>
              <Form
                onSubmit={this.handleFormSubmit}
                id='endorseForm'
                {...formItemLayout}
              >
                {
                  getFormItems.call(this, {
                    formName: 'application_no',
                    type: 'alphanumeric',
                    label: LANG_STRINGS.applicationNumber,
                    initialValue: detailsData ? get(detailsData, 'ApplicationNo', '') : '',
                    validator: validator.checkValidator
                  })
                }
                {
                  this.getPolicyHolderData()
                }
                {
                  (!brandLoading && !modelLoading) && this.getMototCycleData()
                }
                <Button
                  type='primary'
                  className='form-btn'
                  htmlType='submit'
                  key='submit'
                >
                  <IntlMessages id={LANG_STRINGS.submit} />
                </Button>
              </Form>
            </CircularLoader>
        }
      </EndorseContainerStyle>
    )
  }
}
const BukalapakContainerWrapped = Form.create()(BukalapakContainer)
export default connect(
  state => ({
    getPolicyDetailResult: state.Policy.getPolicyDetailResult,
    policyDetailLoading: state.Loading.POLICY_DETAILS,
    policyDetailError: state.Error.POLICY_DETAILS,
    brandLoading: state.Loading.GET_BIKE_BRAND,
    modelLoading: state.Loading.GET_BIKE_MODEL,
    bikeBrandList: state.Endorsement.brandTags,
    bikeModelList: state.Endorsement.modelTags,
    tagModelStatus: state.Endorsement.tagModelStatus,
    tagBrandStatus: state.Endorsement.tagBrandStatus,
    gosureDetailsMessage: state.Endorsement.gosureDetailsMessage,
    submitEndorseLoading: state.Loading.SUBMIT_GOSURE_ENDORSE,
    submitEndorseError: state.Error.SUBMIT_GOSURE_ENDORSE,
    detailsData: state.Policy.detailsData
  }),
  {
    getPolicyDetails,
    resetGosureEndorseRedux,
    getBikeBrandList,
    getBikeModelList,
    submitGosureEndorseForm
  }
)(injectIntl(BukalapakContainerWrapped))
