import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import { GosureVehicleContainerStyle, SendoFormContainer } from './index.style'
import { Row, Col, Form, Button, notification, Alert } from 'antd'
import _ from 'lodash'
import IntlMessages from '../../../../../components/utility/intlMessages'
import policyAction from '../../../../../redux/policy/actions'
import CircularLoader from '../../../../../components/CircularLoader'
import moment from 'moment-timezone'
import endoseActions from '../../../../../redux/Endorsement/actions'
import { ERROR_STRINGS } from '../../../../../constants/lang'
import { getFormItems, errorHandler } from '../../../../../components/utility/formItems'
import validator from '../../../../../helpers/validator'
import FileUploadSection from '../../../GosureEndorsement/componets/FileUploadSection'
import EndorseWelcome from '../../ThankYouComponent'

const { getPolicyDetails } = policyAction
const { submitGosureEndorseForm, resetGosureEndorseRedux } = endoseActions
class GosureVehicleEndorsementContainer extends Component {
  constructor (props) {
    super(props)
    this.state = {
      imageUrls: {
        top: '',
        bottom: '',
        left: '',
        right: ''
      },
      buttonDisabled: true
    }
  }
  static propTypes = {
    id: PropTypes.string
  }

  async componentDidMount () {
    const { id } = this.props
    await this.props.getPolicyDetails(id)
  }

  componentWillReceiveProps (nextProps) {
    const { submitSendoError, gosureDetailsMessage } = nextProps
    errorHandler.call(this, {
      submitError: submitSendoError,
      detailMessage: gosureDetailsMessage,
      resetFunction: () => this.props.resetGosureEndorseRedux(['gosureDetailsMessage'])
    })
  }

  leftSection = () => {
    return (
      <React.Fragment>
        {
          getFormItems.call(this, {
            formName: 'ktp',
            type: 'alphanumeric',
            label: 'Nomor KTP',
            placeHolder: 'Masukkan Nomor KTP',
            required: true,
            validator: validator.validateIdentityKtp
          })
        }
        {
          getFormItems.call(this, {
            formName: 'chassis_number',
            type: 'alphanumeric',
            label: 'Nomor Rangka',
            placeHolder: 'Masukkan Nomor Rangka',
            required: true,
            validator: validator.checkValidator
          })
        }
        {
          getFormItems.call(this, {
            formName: 'engine_number',
            type: 'alphanumeric',
            label: 'Nomor Mesin',
            placeHolder: 'Masukkan Nomor Mesin',
            required: true,
            validator: validator.checkValidator
          })
        }
      </React.Fragment>
    )
  }

  rightSection = () => {
    return (
      <React.Fragment>
        {
          getFormItems.call(this, {
            formName: 'vehicle_color',
            type: 'alphanumeric',
            label: 'Warna Mobil',
            placeHolder: 'Masukkan Warna Mobil',
            required: true,
            validator: validator.validateColor
          })
        }
        {
          getFormItems.call(this, {
            formName: 'vehicle_plate',
            type: 'alphanumeric',
            label: 'Plat Nomor',
            placeHolder: 'Masukkan Plat Nomor',
            required: true,
            validator: validator.checkPlateNumber
          })
        }
      </React.Fragment>
    )
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  handleFormSubmit = async (e) => {
    e.preventDefault()
    const { buttonDisabled, imageUrls } = this.state
    const { top, left, bottom, right } = imageUrls
    const { form, detailsData } = this.props
    const valid = await this.validateForm()
    if (!valid && !buttonDisabled) {
      return
    }

    const formBody = form.getFieldsValue()
    if (formBody.chassis_number === formBody.engine_number) {
      notification.warning({
        message: 'Duplicate Values',
        description:
          'Chasis Number and Engine number having same value'
      })
    } else {
      const body = {
        ...formBody,
        left_photo: left,
        right_photo: right,
        front_photo: top,
        back_photo: bottom,
        recon_time: moment().tz(_.get(detailsData, 'TimezoneLoc', '')).format('YYYY-MM-DD HH:mm:ss')
      }
      this.props.submitGosureEndorseForm({
        body,
        id: this.props.id
      })
    }
  }
  getUploadUrls = (data) => {
    const { imageUrls } = this.state
    const imageObject = Object.keys(data)
    const comparingArray = Object.keys(imageUrls)
    if (_.isEqual(imageObject.sort(), comparingArray.sort())) {
      this.setState({
        imageUrls: data,
        buttonDisabled: false
      })
    }
  }
  showErrorMessage = () => {
    return <Alert
      message={<IntlMessages id={ERROR_STRINGS.error} />}
      description={<IntlMessages id={ERROR_STRINGS.serverError} />}
      type='error'
    />
  }
  render () {
    const {
      policyDetailLoading, detailsData, submitSendoLoading,
      policyDetailError, gosureDetailsMessage
    } = this.props
    const {
      buttonDisabled
    } = this.state
    const isSuccessFulEndorse = (gosureDetailsMessage === 'success') ||
    (_.get(detailsData, 'EndorsementStatus', '') === 'SUCCESS')
    return (
      <GosureVehicleContainerStyle>
        {
          isSuccessFulEndorse ? <EndorseWelcome /> : policyDetailError ? this.showErrorMessage()
            : <CircularLoader isSpining={policyDetailLoading || submitSendoLoading}>
              <Form
                onSubmit={this.handleFormSubmit}
                id='myForm'
                // {...formItemLayout}
              >
                <SendoFormContainer>
                  <h3 className='form-heading'><IntlMessages id='Aktivasi Asuransi' /></h3>
                  <p><IntlMessages id='Untuk mengaktifkan asuransi Anda, isi data kendaraan yang ingin dilindungi. Manfaat Polis tidak dapat diklaim jika data tidak lengkap atau tidak jelas.' /></p>
                  <Row type='flex' gutter={32}>
                    <Col xs={24} sm={24} xl={10} md={10}>
                      {this.leftSection()}
                    </Col>
                    <Col xs={24} sm={24} xl={10} md={10}>
                      {this.rightSection()}
                    </Col>
                  </Row>
                  <Row type='flex'>
                    <p><IntlMessages id='Masukkan foto kendaraan dari sisi depan, belakang dan samping' /></p>
                    <Col span={24}>
                      <div className='fileupload-section'>
                        <FileUploadSection
                          // internalId={_.get(data, 'InternalID', '')}
                          getUploadUrls={this.getUploadUrls}
                        />
                      </div>
                    </Col>

                  </Row>
                  <Row type='flex' justify='center' className='submit-button'>
                    <Col xs={24} sm={23} xl={7} md={7}>
                      <Button
                        disabled={buttonDisabled}
                        type='primary'
                        className='form-btn'
                        htmlType='submit'
                        key='submit'
                      >
                        <IntlMessages id='Kirim' />
                      </Button>
                    </Col>
                  </Row>
                </SendoFormContainer>
              </Form>
            </CircularLoader>
        }
      </GosureVehicleContainerStyle>
    )
  }
}
const GosureVehicleEndorsementContainerWrapped = Form.create()(GosureVehicleEndorsementContainer)
export default connect(
  state => ({
    getPolicyDetailResult: state.Policy.getPolicyDetailResult,
    policyDetailLoading: state.Loading.POLICY_DETAILS,
    policyDetailError: state.Error.POLICY_DETAILS,
    gosureDetailsMessage: state.Endorsement.gosureDetailsMessage,
    submitGosureLoading: state.Loading.SUBMIT_GOSURE_ENDORSE,
    submitGosureError: state.Error.SUBMIT_GOSURE_ENDORSE,
    detailsData: state.Policy.detailsData,
    submitSendoLoading: state.Loading.SUBMIT_GOSURE_ENDORSE,
    submitSendoError: state.Error.SUBMIT_GOSURE_ENDORSE
  }),
  {
    getPolicyDetails,
    submitGosureEndorseForm,
    resetGosureEndorseRedux
  }
)(injectIntl(GosureVehicleEndorsementContainerWrapped))
