import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import { Row, Col, Form, Button, notification, Checkbox } from 'antd'
import _ from 'lodash/object'
import IntlMessages from '../../../../../components/utility/intlMessages'
import policyAction from '../../../../../redux/policy/actions'
import CircularLoader from '../../../../../components/CircularLoader'
import moment from 'moment'
import endorseActions from '../../../../../redux/Endorsement/actions'
import { SendoContainerStyle, SendoFormContainer, PolicyInsuredStyle } from './index.style'
import { showErrorMessage } from '../../../../../helpers/errorUtils'
import { LANG_STRINGS } from '../../../../../constants/lang'
import { getFormItems } from '../../../../../components/utility/formItems'
import validator from '../../../../../helpers/validator'
import { ENDORSE_LANG, SENDO_POICY_HOLDER_INFO } from '../../../constants'
import SendoThankYou from '../SendoPersonalAccidentThankYou'

const { getPolicyDetails } = policyAction
const { submitGosureEndorseForm, resetGosureEndorseRedux, getNationalityData } = endorseActions

class SendoPersonalAccidentContainer extends Component {
  constructor (props) {
    super(props)
    this.state = {
      insuredFieldDisabled: false
    }
  }
  static propTypes = {
    id: PropTypes.string
  }

  async componentDidMount () {
    const { id } = this.props
    await this.props.getPolicyDetails(id)
    await this.props.getNationalityData()
  }

  componentWillReceiveProps (nextProps) {
    const { submitSendoError, gosureDetailsMessage } = nextProps
    if (submitSendoError && gosureDetailsMessage && (gosureDetailsMessage !== 'success')) {
      notification['error']({
        message: this.intlText({ id: 'Error' }),
        description: submitSendoError && gosureDetailsMessage
          ? this.intlText({ id: gosureDetailsMessage }) : ''
      })
      //   // this is clear the error messsage if any left after popup show
      this.props.resetGosureEndorseRedux(['gosureDetailsMessage'])
    }
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  handleFormSubmit = async (e) => {
    e.preventDefault()
    const { form } = this.props
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const formBody = form.getFieldsValue()
    const body = {
      identity_number: formBody.policyHolderPassport,
      name: formBody.policyHolderName,
      email: formBody.policyHolderEmail,
      address: formBody.policyHolderAddress,
      insured_details: {
        identity_number: formBody.insuredPassport,
        name: formBody.insuredName,
        dob: formBody.insuredDob.format('YYYY-MM-DD'),
        nationality: formBody.nationality
      }
    }
    this.props.submitGosureEndorseForm({
      body,
      id: this.props.id
    })
  }
  copyPolicyHolderData =(e) => {
    const { form } = this.props
    const formData = form.getFieldsValue()
    const name = formData.policyHolderName
    const idNo = formData.policyHolderPassport

    form.setFieldsValue({
      'insuredName': e.target.checked ? name : '',
      'insuredPassport': e.target.checked ? idNo : ''
    })
    this.setState({
      insuredFieldDisabled: !!e.target.checked
    })
  }
  getTopSection = (detailsData) => {
    return (
      <React.Fragment>
        {
          this.getPolicyHolderName()
        }
      </React.Fragment>
    )
  }
  getBottomSection = (detailsData) => {
    return (
      <React.Fragment>
        <Checkbox onChange={this.copyPolicyHolderData}><IntlMessages id={ENDORSE_LANG.sameAsPolicyHolder} /></Checkbox>
        {
          this.getInsuredInfo()
        }
      </React.Fragment>
    )
  }

  getPolicyHolderName = () => {
    return (
      <PolicyInsuredStyle>
        {
          SENDO_POICY_HOLDER_INFO.map(policyHolder => getFormItems.call(this, policyHolder))
        }
      </PolicyInsuredStyle>
    )
  }

  getInsuredInfo = () => {
    const { form } = this.props
    const formData = form.getFieldsValue()
    let val = (moment(formData.insuredDob).format('YYYY-MM-DD')).split('-').map(item => parseInt(item, 10))
    let age = Math.floor(moment().diff(val, 'months', true) / 12) > 14
    return (
      <PolicyInsuredStyle>

        {
          getFormItems.call(this, {
            formName: 'insuredName',
            type: 'alphanumeric',
            label: LANG_STRINGS.name,
            placeHolder: ENDORSE_LANG.sendoNamePlaceholder,
            required: true,
            disableField: this.state.insuredFieldDisabled,
            validator: validator.checkValidator
          })
        }
        {
          getFormItems.call(this, {
            formName: 'insuredDob',
            type: 'dob',
            label: LANG_STRINGS.dateOfBirth,
            placeHolder: ENDORSE_LANG.sendoDobPlaceholder,
            required: true,
            validator: validator.checkDobOneYearAndAboveSendo
          })
        }
        {

          getFormItems.call(this, {
            formName: 'insuredPassport',
            type: 'alphanumeric',
            label: LANG_STRINGS.idNumberPassPort,
            placeHolder: ENDORSE_LANG.sendoidNumberPassPortPlaceholder,
            required: age,
            disableField: this.state.insuredFieldDisabled,
            validator: validator.checkValidator
          })
        }
        {
          getFormItems.call(this, {
            formName: 'nationality',
            type: 'choices',
            label: LANG_STRINGS.nationality,
            placeHolder: ENDORSE_LANG.sendoNationalityPlaceholder,
            required: true,
            options: this.props.nationalityData || [],
            initialValue: 'Vietnamese',
            optionKey: 'display_name',
            validator: validator.checkValidator
          })
        }
      </PolicyInsuredStyle>
    )
  }

  render () {
    const {
      policyDetailLoading, detailsData, submitSendoLoading,
      policyDetailError, gosureDetailsMessage
    } = this.props
    const isSuccessFulEndorse = gosureDetailsMessage === 'success' || (_.get(detailsData, 'EndorsementStatus', '') === 'SUCCESS')
    const formItemLayout = {
      labelCol: {
        xs: { span: 24 },
        sm: { span: 11 }
      },
      wrapperCol: {
        xs: { span: 24 },
        sm: { span: 11 }
      }
    }
    return (
      <SendoContainerStyle>
        {
          isSuccessFulEndorse ? <SendoThankYou /> : policyDetailError ? showErrorMessage()
            : <CircularLoader isSpining={policyDetailLoading || submitSendoLoading}>
              <h1 className='order-heading'><IntlMessages id={LANG_STRINGS.orderNumber} /> : {_.get(detailsData, 'Request.order_id', '')}</h1>
              <Form
                onSubmit={this.handleFormSubmit}
                id='myForm'
                {...formItemLayout}
              >
                <SendoFormContainer>
                  <div className='name-section'>
                    <IntlMessages id={ENDORSE_LANG.policyHolder} />
                  </div>
                  <Row type='flex' justify='center'>
                    <Col xs={24} sm={23} xl={15} md={15}>
                      {this.getTopSection(detailsData)}
                    </Col>
                  </Row>
                </SendoFormContainer>
                <SendoFormContainer>
                  <div className='name-section'>
                    <IntlMessages id={ENDORSE_LANG.insuredInfo} />
                  </div>
                  <Row type='flex' justify='center'>
                    <Col xs={24} sm={23} xl={15} md={15}>
                      {this.getBottomSection(detailsData)}
                    </Col>
                  </Row>
                  <Row type='flex' justify='center'>
                    <Col xs={24} sm={23} xl={5} md={5}>
                      <Button
                        type='primary'
                        className='form-btn'
                        htmlType='submit'
                        key='submit'
                      >
                        <IntlMessages id={LANG_STRINGS.submit} />
                      </Button>
                    </Col>
                  </Row>
                </SendoFormContainer>
              </Form>
            </CircularLoader>
        }
      </SendoContainerStyle>
    )
  }
}

const SendoPersonalAccidentContainerWrapped = Form.create()(SendoPersonalAccidentContainer)
export default connect(
  state => ({
    getPolicyDetailResult: state.Policy.getPolicyDetailResult,
    policyDetailLoading: state.Loading.POLICY_DETAILS,
    policyDetailError: state.Error.POLICY_DETAILS,
    gosureDetailsMessage: state.Endorsement.gosureDetailsMessage,
    submitSendoLoading: state.Loading.SUBMIT_GOSURE_ENDORSE,
    submitSendoError: state.Error.SUBMIT_GOSURE_ENDORSE,
    detailsData: state.Policy.detailsData,
    nationalityData: state.Endorsement.nationalityData
  }),
  {
    getPolicyDetails,
    getNationalityData,
    resetGosureEndorseRedux,
    submitGosureEndorseForm
  }
)(injectIntl(SendoPersonalAccidentContainerWrapped))
