import { Component } from 'react'
import { get } from 'lodash/object'
import BukalapakContainer from './BukalapakEndorse/components'
import SendoPAEndorsement from './SendoPersonalAccidentProtectionPro'
import SendoBikeEndorsement from './SendoBikeEndorsement'
import GosureVehicleEndorsement from './GoSureVehicleEndorsement'
import GoSureBicycleEndorsement from './GoSureBicycleEndorsement'
class BukalapakEndorse extends Component {
  render () {
    let product = get(this.props, 'match.params.productId', '')
    switch (product) {
      case 'sendo-bike': return (<SendoBikeEndorsement id={get(this.props, 'match.params.id', '')} />)
      case 'sendo': return (<SendoPAEndorsement id={get(this.props, 'match.params.id', '')} />)
      case 'gosure-vehicle': return (<GosureVehicleEndorsement id={get(this.props, 'match.params.id', '')} />)
      case 'bicycle-protection': return (<GoSureBicycleEndorsement id={get(this.props, 'match.params.id', '')} />)
      default:
        return (<BukalapakContainer id={get(this.props, 'match.params.id', '')} />)
    }
  }
}

export default BukalapakEndorse
